pub fn htmlEntityValueLookup(
    mut value: c_uint,
) -> *const htmlEntityDesc {
    unsafe {
        let table = &raw const html40EntitiesTable as *const htmlEntityDesc;
        let mut lo: usize = 0;
        let mut hi: usize =
            (::core::mem::size_of::<[htmlEntityDesc; 253]>() as usize)
                .wrapping_div(::core::mem::size_of::<htmlEntityDesc>() as usize);

