            *out = (((byte as c_int >> 6) & 0x1f) | 0xc0) as c_uchar;
            *out.offset(1) = ((byte as c_int & 0x3f) | 0x80) as c_uchar;
            out = out.offset(2);
            in_0 = in_0.offset(1);
            continue;
        }

        let out_rem = outend.offset_from(out) as isize;
        let in_rem = inend.offset_from(in_0) as isize;
        let max_copy = if in_rem < out_rem { in_rem } else { out_rem };

        let mut n = 0isize;
