#[no_mangle]
pub unsafe extern "C" fn __xmlRaiseError(
    mut schannel: xmlStructuredErrorFunc,
    mut channel: xmlGenericErrorFunc,
    mut data: *mut c_void,
    mut ctx: *mut c_void,
    mut nod: *mut c_void,
    mut domain: c_int,
    mut code: c_int,
    mut level: xmlErrorLevel,
    mut file: *const c_char,
    mut line: c_int,
    mut str1: *const c_char,
    mut str2: *const c_char,
    mut str3: *const c_char,
    mut int1: c_int,
    mut col: c_int,
    mut msg: *const c_char,
    mut args: ...
) {
    let mut ctxt: xmlParserCtxtPtr = ::core::ptr::null_mut();
    let mut node: xmlNodePtr = nod as xmlNodePtr;
    let mut str: *mut c_char = ::core::ptr::null_mut();
    let mut input: xmlParserInputPtr = ::core::ptr::null_mut();
    let last_error = __xmlLastError();
    let mut to: xmlErrorPtr = last_error;
    let mut baseptr: xmlNodePtr = ::core::ptr::null_mut();

    if code == XML_ERR_OK as c_int {
        return;
    }
    if *__xmlGetWarningsDefaultValue() == 0
        && level as c_uint == XML_ERR_WARNING as c_int as c_uint
    {
        return;
    }

    let parser_domain = domain == XML_FROM_PARSER as c_int
        || domain == XML_FROM_HTML as c_int
        || domain == XML_FROM_DTD as c_int
        || domain == XML_FROM_NAMESPACE as c_int
        || domain == XML_FROM_IO as c_int
        || domain == XML_FROM_VALID as c_int;

    if parser_domain {
        ctxt = ctx as xmlParserCtxtPtr;
        if !ctxt.is_null() {
            if level as c_uint == XML_ERR_WARNING as c_int as c_uint {
                if (*ctxt).nbWarnings as c_int >= XML_MAX_ERRORS {
                    return;
                }
                (*ctxt).nbWarnings = ((*ctxt).nbWarnings as c_int + 1) as c_ushort;
            } else {
                if (*ctxt).nbErrors as c_int >= XML_MAX_ERRORS {
                    return;
                }
                (*ctxt).nbErrors = ((*ctxt).nbErrors as c_int + 1) as c_ushort;
            }

            let sax = (*ctxt).sax;
            if schannel.is_none()
                && !sax.is_null()
                && (*sax).initialized == XML_SAX2_MAGIC
                && (*sax).serror.is_some()
            {
                schannel = (*sax).serror;
                data = (*ctxt).userData;
            }
        }
    }

    if schannel.is_none() {
        let global_schannel = *__xmlStructuredError();
        if global_schannel.is_some() {
            schannel = global_schannel;
            data = *__xmlStructuredErrorContext();
        }
    }

    if msg.is_null() {
        str = xmlStrdup(
            b"No error message provided\0" as *const u8 as *const c_char as *mut xmlChar,
        ) as *mut c_char;
    } else {
        let mut size: c_int = 150;
        let mut prev_size: c_int = -1;
        let mut chars: c_int;
        let mut larger: *mut c_char;
        let mut ap: ::core::ffi::VaListImpl;

        str = xmlMalloc.expect("non-null function pointer")(size as size_t) as *mut c_char;
        if !str.is_null() {
            while size < 64000 {
                ap = args.clone();
                chars = vsnprintf(str, size as size_t, msg, ap.as_va_list());
                if chars > -1 && chars < size {
                    if prev_size == chars {
                        break;
                    }
                    prev_size = chars;
                }
                if chars > -1 {
                    size += chars + 1;
                } else {
                    size += 100;
                }
                larger = xmlRealloc.expect("non-null function pointer")(
                    str as *mut c_void,
                    size as size_t,
                ) as *mut c_char;
                if larger.is_null() {
                    break;
                }
                str = larger;
            }
        }
    }

    if !ctxt.is_null() {
        if file.is_null() {
            input = (*ctxt).input;
            if !input.is_null() && (*input).filename.is_null() && (*ctxt).inputNr > 1 {
                input = *(*ctxt).inputTab.offset(((*ctxt).inputNr - 2) as isize);
            }
            if !input.is_null() {
                file = (*input).filename;
                line = (*input).line;
                col = (*input).col;
            }
        }
        to = &raw mut (*ctxt).lastError as xmlErrorPtr;
    } else if !node.is_null() && file.is_null() {
        if !(*node).doc.is_null() && !(*(*node).doc).URL.is_null() {
            baseptr = node;
        }

        let mut i: c_int = 0;
        while i < 10
            && !node.is_null()
            && (*node).type_0 as c_uint != XML_ELEMENT_NODE as c_int as c_uint
        {
            node = (*node).parent as xmlNodePtr;
            i += 1;
        }

        if baseptr.is_null()
            && !node.is_null()
            && !(*node).doc.is_null()
            && !(*(*node).doc).URL.is_null()
        {
            baseptr = node;
        }

        if !node.is_null() && (*node).type_0 as c_uint == XML_ELEMENT_NODE as c_int as c_uint {
            line = (*node).line as c_int;
        }
        if line == 0 || line == 65535 {
            line = xmlGetLineNo(node as *const xmlNode) as c_int;
        }
    }

    xmlResetError(to);
    (*to).domain = domain;
    (*to).code = code;
    (*to).message = str;
    (*to).level = level;

    if !file.is_null() {
        (*to).file = xmlStrdup(file as *const xmlChar) as *mut c_char;
    } else if !baseptr.is_null() {
        let mut prev: xmlNodePtr = baseptr;
        let mut href: *mut c_char = ::core::ptr::null_mut();
        let mut inclcount: c_int = 0;

        while !prev.is_null() {
            if (*prev).prev.is_null() {
                prev = (*prev).parent as xmlNodePtr;
            } else {
                prev = (*prev).prev as xmlNodePtr;
                let prev_type = (*prev).type_0 as c_uint;
                if prev_type == XML_XINCLUDE_START as c_int as c_uint {
                    if inclcount > 0 {
                        inclcount -= 1;
                    } else {
                        href = xmlGetProp(
                            prev as *const xmlNode,
                            b"href\0" as *const u8 as *const c_char as *mut xmlChar,
                        ) as *mut c_char;
                        if !href.is_null() {
                            break;
                        }
                    }
                } else if prev_type == XML_XINCLUDE_END as c_int as c_uint {
                    inclcount += 1;
                }
            }
        }

        if !href.is_null() {
            (*to).file = href;
        } else {
            (*to).file = xmlStrdup((*(*baseptr).doc).URL) as *mut c_char;
        }
        if (*to).file.is_null() && !node.is_null() && !(*node).doc.is_null() {
            (*to).file = xmlStrdup((*(*node).doc).URL) as *mut c_char;
        }
    }

    (*to).line = line;
    if !str1.is_null() {
        (*to).str1 = xmlStrdup(str1 as *const xmlChar) as *mut c_char;
    }
    if !str2.is_null() {
        (*to).str2 = xmlStrdup(str2 as *const xmlChar) as *mut c_char;
    }
    if !str3.is_null() {
        (*to).str3 = xmlStrdup(str3 as *const xmlChar) as *mut c_char;
    }
    (*to).int1 = int1;
    (*to).int2 = col;
    (*to).node = node as *mut c_void;
    (*to).ctxt = ctx;

    if to != last_error {
        xmlCopyError(to as *const xmlError, last_error);
    }

    if let Some(scb) = schannel {
        scb(data, to as *const xmlError);
        return;
    }

    if !ctxt.is_null() && channel.is_none() && (*__xmlStructuredError()).is_none() && !(*ctxt).sax.is_null() {
        let sax = (*ctxt).sax;
        if level as c_uint == XML_ERR_WARNING as c_int as c_uint {
            channel = (*sax).warning as xmlGenericErrorFunc;
        } else {
            channel = (*sax).error as xmlGenericErrorFunc;
        }
        data = (*ctxt).userData;
    } else if channel.is_none() {
        channel = *__xmlGenericError();
        if !ctxt.is_null() {
            data = ctxt as *mut c_void;
        } else {
            data = *__xmlGenericErrorContext();
        }
    }

    let Some(ch) = channel else {
        return;
    };

    if ch
        == xmlParserError
            as unsafe extern "C" fn(*mut c_void, *const c_char, ...) -> ()
        || ch
            == xmlParserWarning
                as unsafe extern "C" fn(*mut c_void, *const c_char, ...) -> ()
        || ch
            == xmlParserValidityError
                as unsafe extern "C" fn(*mut c_void, *const c_char, ...) -> ()
        || ch
            == xmlParserValidityWarning
                as unsafe extern "C" fn(*mut c_void, *const c_char, ...) -> ()
    {
        xmlReportError(to, ctxt, str, None, NULL);
    } else if ::core::mem::transmute::<xmlGenericErrorFunc, Option<unsafe extern "C" fn() -> ()>>(Some(ch))
        == ::core::mem::transmute::<
            Option<unsafe extern "C" fn(*mut FILE, *const c_char, ...) -> c_int>,
            Option<unsafe extern "C" fn() -> ()>,
        >(Some(
            fprintf as unsafe extern "C" fn(*mut FILE, *const c_char, ...) -> c_int,
        ))
        || Some(ch)
            == Some(
                xmlGenericErrorDefaultFunc
                    as unsafe extern "C" fn(*mut c_void, *const c_char, ...) -> (),
            )
    {
        xmlReportError(to, ctxt, str, Some(ch), data);
    } else {
        ch(data, b"%s\0" as *const u8 as *const c_char, str);
    };
}
