unsafe fn xmlParse3986Segment(
    mut str: *mut *const c_char,
    mut forbid: c_char,
    mut empty: c_int,
) -> c_int {
    #[inline(always)]
    fn is_hex(b: u8) -> bool {
        b.wrapping_sub(b'0') <= 9
            || b.wrapping_sub(b'a') <= 5
            || b.wrapping_sub(b'A') <= 5
    }

    #[inline(always)]
    fn is_unreserved_or_subdelim_or_extra(b: u8) -> bool {
        b.wrapping_sub(b'a') <= (b'z' - b'a')
            || b.wrapping_sub(b'A') <= (b'Z' - b'A')
            || b.wrapping_sub(b'0') <= 9
            || matches!(
                b,
                b'-'
                    | b'.'
                    | b'_'
                    | b'~'
                    | b'!'
                    | b'$'
                    | b'&'
                    | b'('
                    | b')'
                    | b'*'
                    | b'+'
                    | b','
                    | b';'
                    | b'='
                    | b'\''
                    | b':'
                    | b'@'
            )
    }

    let mut cur = unsafe {
        // SAFETY: `str` is provided by the caller and must be a valid pointer to a C string pointer, as required by the original function.
        *str
    };
    let forbid_u = forbid as u8;

    let first = unsafe {
        // SAFETY: `cur` points into the caller-provided C string; reading the current byte matches the original function's behavior.
        *cur as u8
    };

    let first_ok = if first == b'%' {
        let b1 = unsafe {
            // SAFETY: The original function unconditionally reads cur+1 and cur+2 when current byte is '%'; we preserve that exact behavior.
            *cur.add(1) as u8
        };
        let b2 = unsafe {
            // SAFETY: The original function unconditionally reads cur+1 and cur+2 when current byte is '%'; we preserve that exact behavior.
            *cur.add(2) as u8
        };
        is_hex(b1) && is_hex(b2)
    } else {
        is_unreserved_or_subdelim_or_extra(first)
    };

    if !first_ok {
        if empty != 0 {
            return 0;
        }
        return 1;
    }

    loop {
        let b = unsafe {
            // SAFETY: `cur` points into the same caller-provided C string; reading the current byte matches the original function's behavior.
            *cur as u8
        };

        if b == forbid_u {
            break;
        }

        if b == b'%' {
            let b1 = unsafe {
                // SAFETY: The original function unconditionally reads cur+1 and cur+2 when current byte is '%'; we preserve that exact behavior.
                *cur.add(1) as u8
            };
            let b2 = unsafe {
                // SAFETY: The original function unconditionally reads cur+1 and cur+2 when current byte is '%'; we preserve that exact behavior.
                *cur.add(2) as u8
            };
            if !(is_hex(b1) && is_hex(b2)) {
                break;
            }
            cur = unsafe {
                // SAFETY: Advancing by 3 after consuming a validated percent-encoded triplet matches the original function's pointer arithmetic.
                cur.add(3)
            };
        } else if is_unreserved_or_subdelim_or_extra(b) {
            cur = unsafe {
                // SAFETY: Advancing by 1 after consuming a valid segment byte matches the original function's pointer arithmetic.
                cur.add(1)
            };
        } else {
            break;
        }
    }

    unsafe {
        // SAFETY: `str` is a valid out-parameter pointer supplied by the caller; storing the updated cursor matches the original function.
        *str = cur;
    }
    0
}
