unsafe extern "C" fn xmlFileOpenW(
    mut filename: *const c_char,
) -> *mut c_void {
    let path: *const c_char;

    if strcmp(filename, b"-\0" as *const u8 as *const c_char) == 0 {
        return stdout as *mut c_void;
    }

    if xmlStrncasecmp(
        filename as *mut xmlChar,
        b"file://localhost/\0" as *const u8 as *const c_char as *mut xmlChar,
        17 as c_int,
    ) == 0
    {
        // Matches original behavior exactly: skip the "file://localhost" prefix,
        // leaving the leading '/' in place.
        // SAFETY: `filename` points to a NUL-terminated string and we only compute
        // the same in-bounds pointer offset used by the original code.
        path = unsafe { filename.add(16) };
    } else if xmlStrncasecmp(
        filename as *mut xmlChar,
        b"file:///\0" as *const u8 as *const c_char as *mut xmlChar,
        8 as c_int,
    ) == 0
    {
        // Matches original behavior exactly: skip "file://" and keep one leading '/'.
        // SAFETY: `filename` points to a NUL-terminated string and we only compute
        // the same in-bounds pointer offset used by the original code.
        path = unsafe { filename.add(7) };
    } else {
