    }

    if path.is_null() {
        return ::core::ptr::null_mut::<c_void>();
    }

    let fd = fopen(path, b"wb\0" as *const u8 as *const c_char);
    if fd.is_null() {
        xmlIOErr(0 as c_int, path);
    }
