fn xmlRegStatePush(mut ctxt: xmlRegParserCtxtPtr) -> xmlRegStatePtr { unsafe {
    let nb_states = (*ctxt).nbStates;
    if nb_states >= (*ctxt).maxStates {
        let new_size = if (*ctxt).maxStates != 0 {
            (*ctxt).maxStates * 2
        } else {
            4
        } as size_t;

        let tmp = xmlRealloc.expect("non-null function pointer")(
            (*ctxt).states as *mut c_void,
            new_size.wrapping_mul(::core::mem::size_of::<xmlRegStatePtr>() as size_t),
        ) as *mut xmlRegStatePtr;

        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding state\0" as *const u8 as *const c_char,
            );
            return ::core::ptr::null_mut();
        }

        (*ctxt).states = tmp;
        (*ctxt).maxStates = new_size as c_int;
    }

    let state = xmlRegNewState(ctxt);
    if state.is_null() {
        return ::core::ptr::null_mut();
    }

    (*state).no = nb_states;
    (*ctxt).nbStates = nb_states + 1;
    // SAFETY: `states` has capacity for index `nb_states` due to the growth check above, and `nb_states` is the previous valid insertion index.
    *(*ctxt).states.add(nb_states as usize) = state;
    state
} }
