fn htmlParseLookupSequence(
    mut ctxt: htmlParserCtxtPtr,
    mut first: xmlChar,
    mut next: xmlChar,
    mut third: xmlChar,
    mut ignoreattrval: c_int,
) -> c_int {
    unsafe {
        let in_0 = (*ctxt).input as htmlParserInputPtr;
        if in_0.is_null() {
            return -1;
        }

        let mut base = (*ctxt).checkIndex as size_t;
        let mut quote = (*ctxt).endCheckState;
        let buf = (*in_0).cur;
        let mut len = (*in_0).end.offset_from(buf) as c_long as size_t;

        if third != 0 {
            len = len.wrapping_sub(2);
        } else if next != 0 {
            len = len.wrapping_sub(1);
        }

        let first_i = first as c_int;
        let next_i = next as c_int;
        let third_i = third as c_int;
        let check_third = third_i != 0;
        let check_next = next_i != 0;

        while base < len {
            if base >= (INT_MAX / 2) as size_t {
                (*ctxt).checkIndex = 0 as c_long;
                (*ctxt).endCheckState = 0;
                return base.wrapping_sub(2) as c_int;
            }

            // SAFETY: `base < len`, and `len` was derived from `end.offset_from(cur)` adjusted
            // downward to ensure any lookahead of 1 or 2 bytes remains within `[cur, end)`.
            let b0 = *buf.add(base) as c_int;

            if ignoreattrval != 0 {
                if quote != 0 {
                    if b0 == quote {
                        quote = 0;
                    }
                    base = base.wrapping_add(1);
                    continue;
                } else if b0 == '"' as c_int || b0 == '\'' as c_int {
                    quote = b0;
                    base = base.wrapping_add(1);
                    continue;
                }
            }

            if b0 == first_i {
                if check_third {
                    // SAFETY: `base < len` and `len` was reduced by 2 when `third != 0`,
                    // so `base + 1` and `base + 2` are valid positions within the buffer.
                    if *buf.add(base + 1) as c_int == next_i
                        && *buf.add(base + 2) as c_int == third_i
                    {
                        (*ctxt).checkIndex = 0 as c_long;
                        (*ctxt).endCheckState = 0;
                        return base as c_int;
                    }
                } else if check_next {
                    // SAFETY: `base < len` and `len` was reduced by 1 when `next != 0 && third == 0`,
                    // so `base + 1` is a valid position within the buffer.
                    if *buf.add(base + 1) as c_int == next_i {
                        (*ctxt).checkIndex = 0 as c_long;
                        (*ctxt).endCheckState = 0;
                        return base as c_int;
                    }
                } else {
                    (*ctxt).checkIndex = 0 as c_long;
                    (*ctxt).endCheckState = 0;
                    return base as c_int;
                }
            }

            base = base.wrapping_add(1);
        }

        (*ctxt).checkIndex = base as c_long;
        (*ctxt).endCheckState = quote;
        -1
    }
}
