fn htmlParseCharDataInternal(
    mut ctxt: htmlParserCtxtPtr,
    mut readahead: c_int,
) { unsafe {
    let mut buf: [xmlChar; 1006] = [0; 1006];
    let mut nbchar: c_int = 0;
    let mut cur: c_int;
    let mut l: c_int = 0;

    #[inline(always)]
    unsafe fn flush_char_data(
        ctxt: htmlParserCtxtPtr,
        buf: *mut xmlChar,
        nbchar: c_int,
    ) {
        if !(*ctxt).sax.is_null() && (*ctxt).disableSAX == 0 {
            if areBlanks(ctxt, buf, nbchar) != 0 {
                if (*ctxt).keepBlanks != 0 {
                    if let Some(characters) = (*(*ctxt).sax).characters {
                        characters((*ctxt).userData, buf, nbchar);
                    }
                } else if let Some(ignorable) = (*(*ctxt).sax).ignorableWhitespace {
                    ignorable((*ctxt).userData, buf, nbchar);
                }
            } else {
                htmlCheckParagraph(ctxt);
                if let Some(characters) = (*(*ctxt).sax).characters {
                    characters((*ctxt).userData, buf, nbchar);
                }
            }
        }
    }

    if readahead != 0 {
        buf[0] = readahead as xmlChar;
        nbchar = 1;
    }

    cur = htmlCurrentChar(ctxt as xmlParserCtxtPtr, &raw mut l);

    while (cur != '<' as i32 || (*ctxt).token == '<' as i32)
        && (cur != '&' as i32 || (*ctxt).token == '&' as i32)
        && cur != 0
    {
        let valid = if cur < 0x100 {
            (0x9 <= cur && cur <= 0xa) || cur == 0xd || 0x20 <= cur
        } else {
            (0x100 <= cur && cur <= 0xd7ff)
                || (0xe000 <= cur && cur <= 0xfffd)
                || (0x10000 <= cur && cur <= 0x10ffff)
        };

        if !valid {
            htmlParseErrInt(
                ctxt as xmlParserCtxtPtr,
                XML_ERR_INVALID_CHAR,
                b"Invalid char in CDATA 0x%X\n\0" as *const u8 as *const c_char,
                cur,
            );
        } else if l == 1 {
            buf[nbchar as usize] = cur as xmlChar;
            nbchar += 1;
        } else {
            nbchar += xmlCopyChar(
                l,
                // SAFETY: nbchar is maintained within buffer capacity; multi-byte chars are copied exactly as in the original code.
                buf.as_mut_ptr().add(nbchar as usize),
                cur,
            );
        }

        let input = (*ctxt).input;
        if *(*input).cur as c_int == '\n' as i32 {
            (*input).line += 1;
            (*input).col = 1;
        } else {
            (*input).col += 1;
        }
        (*ctxt).token = 0;
        // SAFETY: l is returned by htmlCurrentChar for the current input position; advancing by l matches original parser logic.
        (*input).cur = (*input).cur.offset(l as isize);

        if nbchar >= HTML_PARSER_BIG_BUFFER_SIZE {
            buf[nbchar as usize] = 0;
            flush_char_data(ctxt, buf.as_mut_ptr(), nbchar);
            nbchar = 0;

            if (*input).cur.offset_from((*input).base) as c_long > (2 * INPUT_CHUNK) as c_long
                && (*input).end.offset_from((*input).cur) as c_long
                    < (2 * INPUT_CHUNK) as c_long
            {
                xmlParserShrink(ctxt as xmlParserCtxtPtr);
            }
        }

        cur = htmlCurrentChar(ctxt as xmlParserCtxtPtr, &raw mut l);
    }

    if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
        return;
    }
    if nbchar != 0 {
        buf[nbchar as usize] = 0;
        flush_char_data(ctxt, buf.as_mut_ptr(), nbchar);
    }
} }
