fn xmlFAEliminateEpsilonTransitions(mut ctxt: xmlRegParserCtxtPtr) { unsafe {
    // SAFETY: caller provides a valid parser context pointer per original function contract.
    if (*ctxt).states.is_null() {
        return;
    }

    xmlFAEliminateSimpleEpsilonTransitions(ctxt);

    let states = (*ctxt).states;
    let nb_states = (*ctxt).nbStates;

    let mut statenr: c_int = 0;
    while statenr < nb_states {
        // SAFETY: states points to an array of nb_states entries.
        let state = *states.offset(statenr as isize);
        if !state.is_null()
            && (*state).type_0 as c_uint == XML_REGEXP_UNREACH_STATE as c_int as c_uint
        {
            xmlRegFreeState(state);
            // SAFETY: same indexed slot as read above.
            *states.offset(statenr as isize) = ::core::ptr::null_mut::<xmlRegState>();
        }
        statenr += 1;
    }

    let mut has_epsilon: c_int = 0;
    statenr = nb_states - 1;
    while statenr >= 0 {
        // SAFETY: states points to an array of nb_states entries.
        let state = *states.offset(statenr as isize);
        if !state.is_null() {
            if (*state).nbTrans == 0
                && (*state).type_0 as c_uint != XML_REGEXP_FINAL_STATE as c_int as c_uint
            {
                (*state).type_0 = XML_REGEXP_SINK_STATE;
            }

            let trans_base = (*state).trans;
            let nb_trans = (*state).nbTrans;
            let mut transnr: c_int = 0;
            while transnr < nb_trans {
                // SAFETY: trans_base points to nb_trans transitions.
                let trans = trans_base.offset(transnr as isize);
                if (*trans).atom.is_null() && (*trans).to >= 0 {
                    if (*trans).to == statenr {
                        (*trans).to = -1;
                    } else if (*trans).count < 0 {
                        let newto = (*trans).to;
                        has_epsilon = 1;
                        (*trans).to = -2;
                        (*state).mark = XML_REGEXP_MARK_START;
                        xmlFAReduceEpsilonTransitions(ctxt, statenr, newto, (*trans).counter);
                        xmlFAFinishReduceEpsilonTransitions(ctxt, newto);
                        (*state).mark = XML_REGEXP_MARK_NORMAL;
                    }
                }
                transnr += 1;
            }
        }
        statenr -= 1;
    }

    if has_epsilon != 0 {
        statenr = 0;
        while statenr < nb_states {
            // SAFETY: states points to an array of nb_states entries.
            let state = *states.offset(statenr as isize);
            if !state.is_null() {
                let trans_base = (*state).trans;
                let nb_trans = (*state).nbTrans;
                let mut transnr: c_int = 0;
                while transnr < nb_trans {
                    // SAFETY: trans_base points to nb_trans transitions.
                    let trans = trans_base.offset(transnr as isize);
                    if (*trans).atom.is_null() && (*trans).count < 0 && (*trans).to >= 0 {
                        (*trans).to = -1;
                    }
                    transnr += 1;
                }
            }
            statenr += 1;
        }
    }

    statenr = 0;
    while statenr < nb_states {
        // SAFETY: states points to an array of nb_states entries.
        let state = *states.offset(statenr as isize);
        if !state.is_null() {
            (*state).reached = XML_REGEXP_MARK_NORMAL;
        }
        statenr += 1;
    }

    // SAFETY: original code assumes state 0 exists when states is non-null.
    let mut state = *states.offset(0);
    if !state.is_null() {
        (*state).reached = XML_REGEXP_MARK_START;
    }

    while !state.is_null() {
        let mut target: xmlRegStatePtr = ::core::ptr::null_mut::<xmlRegState>();
        (*state).reached = XML_REGEXP_MARK_VISITED;

        let trans_base = (*state).trans;
        let nb_trans = (*state).nbTrans;
        let mut transnr: c_int = 0;
        while transnr < nb_trans {
            // SAFETY: trans_base points to nb_trans transitions.
            let trans = trans_base.offset(transnr as isize);
            let to = (*trans).to;
            if to >= 0 && (!(*trans).atom.is_null() || (*trans).count >= 0) {
                // SAFETY: to is a valid state index by automaton invariants preserved by original code.
                let dst_slot = states.offset(to as isize);
                let dst = *dst_slot;
                if !dst.is_null()
                    && (*dst).reached as c_uint == XML_REGEXP_MARK_NORMAL as c_int as c_uint
                {
                    (*dst).reached = XML_REGEXP_MARK_START;
                    target = dst;
                }
            }
            transnr += 1;
        }

        if target.is_null() {
            statenr = 1;
            while statenr < nb_states {
                // SAFETY: states points to an array of nb_states entries.
                let cand = *states.offset(statenr as isize);
                if !cand.is_null()
                    && (*cand).reached as c_uint == XML_REGEXP_MARK_START as c_int as c_uint
                {
                    target = cand;
                    break;
                }
                statenr += 1;
            }
        }
        state = target;
    }

    statenr = 0;
    while statenr < nb_states {
        // SAFETY: states points to an array of nb_states entries.
        let state = *states.offset(statenr as isize);
        if !state.is_null()
            && (*state).reached as c_uint == XML_REGEXP_MARK_NORMAL as c_int as c_uint
        {
            xmlRegFreeState(state);
            // SAFETY: same indexed slot as read above.
            *states.offset(statenr as isize) = ::core::ptr::null_mut::<xmlRegState>();
        }
        statenr += 1;
    }
} }
