pub unsafe extern "C" fn xmlFileClose(mut context: *mut c_void) -> c_int {
    if context.is_null() {
        return -1;
    }

    let fil = context as *mut FILE;

    if fil == stdout || fil == stderr {
        if fflush(fil) < 0 {
            xmlIOErr(0, b"fflush()\0" as *const u8 as *const c_char);
