unsafe fn xmlRegAtomAddRange(
    mut ctxt: xmlRegParserCtxtPtr,
    mut atom: xmlRegAtomPtr,
    mut neg: c_int,
    mut type_0: xmlRegAtomType,
    mut start: c_int,
    mut end: c_int,
    mut blockName: *mut xmlChar,
) -> xmlRegRangePtr {
    if atom.is_null() {
        (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
        xmlRegexpErrCompile(
            ctxt,
            b"add range: atom is NULL\0" as *const u8 as *const c_char,
        );
        return ::core::ptr::null_mut::<xmlRegRange>();
    }

    let atom_ref = &mut *atom;

    if atom_ref.type_0 as c_uint != XML_REGEXP_RANGES as c_int as c_uint {
        (*ctxt).error = XML_REGEXP_COMPILE_ERROR as c_int;
        xmlRegexpErrCompile(
            ctxt,
            b"add range: atom is not ranges\0" as *const u8 as *const c_char,
        );
        return ::core::ptr::null_mut::<xmlRegRange>();
    }

    let nb = atom_ref.nbRanges;
    let max = atom_ref.maxRanges;

    if max == 0 {
        let new_max = 4 as c_int;
        let new_ranges = xmlMalloc.expect("non-null function pointer")(
            (new_max as size_t)
                .wrapping_mul(::core::mem::size_of::<xmlRegRangePtr>() as size_t),
        ) as *mut xmlRegRangePtr;
        if new_ranges.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding ranges\0" as *const u8 as *const c_char,
            );
            atom_ref.maxRanges = 0 as c_int;
            return ::core::ptr::null_mut::<xmlRegRange>();
        }
        atom_ref.maxRanges = new_max;
        atom_ref.ranges = new_ranges;
    } else if nb >= max {
        let new_max = max * 2 as c_int;
        let tmp = xmlRealloc.expect("non-null function pointer")(
            atom_ref.ranges as *mut c_void,
            (new_max as size_t)
                .wrapping_mul(::core::mem::size_of::<xmlRegRangePtr>() as size_t),
        ) as *mut xmlRegRangePtr;
        if tmp.is_null() {
            xmlRegexpErrMemory(
                ctxt,
                b"adding ranges\0" as *const u8 as *const c_char,
            );
            return ::core::ptr::null_mut::<xmlRegRange>();
        }
        atom_ref.maxRanges = new_max;
        atom_ref.ranges = tmp;
    }

    let range = xmlRegNewRange(ctxt, neg, type_0, start, end);
    if range.is_null() {
        return ::core::ptr::null_mut::<xmlRegRange>();
    }

    (*range).blockName = blockName;
    let idx = atom_ref.nbRanges;
    atom_ref.nbRanges = idx + 1;
    // SAFETY: atom_ref.ranges points to an allocated array with capacity > idx due to the checks/growth above.
    *atom_ref.ranges.add(idx as usize) = range;
    range
}
