pub fn xmlBufAddLen(mut buf: xmlBufPtr, mut len: size_t) -> c_int { unsafe {
    // SAFETY: All raw pointer dereferences below require `buf` to be non-null; this is checked first.
    if buf.is_null() || (*buf).error != 0 {
        return -(1 as c_int);
    }

    // SAFETY: `buf` is non-null as checked above.
    let b = &mut *buf;

    let compat_size = b.compat_size;
    if b.size != compat_size as size_t && compat_size < INT_MAX as c_uint {
        b.size = compat_size as size_t;
    }

    let compat_use = b.compat_use;
    if b.use_0 != compat_use as size_t && compat_use < INT_MAX as c_uint {
        b.use_0 = compat_use as size_t;
    }

    let size = b.size;
    let use_0 = b.use_0;
    if len >= size.wrapping_sub(use_0) {
        return -(1 as c_int);
    }

    let new_use = (use_0 as c_ulong).wrapping_add(len as c_ulong) as size_t;
    b.use_0 = new_use;
    // SAFETY: Original function assumes `content` points to a writable buffer of at least `new_use + 1` bytes when bounds check above passes; we preserve that exact precondition.
    *b.content.offset(new_use as isize) = 0 as xmlChar;

    b.compat_size = if size < INT_MAX as size_t {
        size as c_uint
    } else {
        INT_MAX as c_uint
    };

    b.compat_use = if new_use < INT_MAX as size_t {
        new_use as c_uint
    } else {
        INT_MAX as c_uint
    };

    0 as c_int
} }
